# ---- ordered validation ----

def test_type_error_both_args():
    with pytest.raises(TypeError):
        safe_join(123, "a")  # type: ignore
    with pytest.raises(TypeError):
        safe_join("/a", None)  # type: ignore
    with pytest.raises(TypeError):
        safe_join(None, None)  # type: ignore
    with pytest.raises(TypeError):
        safe_join(b"/a", "b")  # type: ignore


def test_type_error_takes_precedence_over_value_error():
    with pytest.raises(TypeError):
        safe_join(123, "/absolute")  # type: ignore
    with pytest.raises(TypeError):
        safe_join(123, "has\x00nul")  # type: ignore


def test_nul_in_either_arg_raises():
    with pytest.raises(ValueError):
        safe_join("/srv/data", "a\x00b")
    with pytest.raises(ValueError):
        safe_join("/srv\x00data", "a")
    with pytest.raises(ValueError):
        safe_join("\x00", "a")
    with pytest.raises(ValueError):
        safe_join("/a", "\x00")


def test_base_must_be_absolute():
    with pytest.raises(ValueError):
        safe_join("srv/data", "a")
    with pytest.raises(ValueError):
        safe_join("", "a")
    with pytest.raises(ValueError):
        safe_join(".", "a")
    with pytest.raises(ValueError):
        safe_join("C:/win", "a")


def test_user_path_absolute_always_rejected():
    with pytest.raises(ValueError):
        safe_join("/srv/data", "/etc/passwd")
    with pytest.raises(ValueError):
        safe_join("/etc", "/etc/passwd")
    with pytest.raises(ValueError):
        safe_join("/", "/")
    with pytest.raises(ValueError):
        safe_join("/a", "/a")
    with pytest.raises(ValueError):
        safe_join("/a", "/a/b")


def test_empty_and_dot_return_root():
    assert safe_join("/srv/data", "") == posixpath.normpath("/srv/data")
    assert safe_join("/srv/data", ".") == "/srv/data"
    assert safe_join("/srv/data/", ".") == "/srv/data"
    assert safe_join("/", "") == "/"
    assert safe_join("/", ".") == "/"
    assert safe_join("/a//b/./", ".") == "/a/b"


def test_sibling_prefix_is_outside():
    with pytest.raises(ValueError):
        safe_join("/srv/data", "../data2/x")
    with pytest.raises(ValueError):
        safe_join("/srv/data", "../data2")
    with pytest.raises(ValueError):
        safe_join("/a/b", "../bc")
    assert safe_join("/srv/data", "../data/x") == "/srv/data/x"


def test_dotdot_inside_is_allowed():
    assert safe_join("/srv/data", "a/../b") == "/srv/data/b"
    assert safe_join("/srv/data", "a/b/../../c") == "/srv/data/c"
    assert safe_join("/a/b/c", "../../d") == "/a/d"
    assert safe_join("/a/b", "././x/./y") == "/a/b/x/y"


def test_backslash_is_ordinary_character():
    # POSIX semantics: only / separates
    assert safe_join("/srv/data", "a\\b") == "/srv/data/a\\b"
    assert safe_join("/srv/data", "..\\..\\etc") == "/srv/data/..\\..\\etc"
    assert safe_join("/srv/data", "a\\..\\b") == "/srv/data/a\\..\\b"


def test_root_slash_covers_everything_absolute():
    assert safe_join("/", "etc/passwd") == "/etc/passwd"
    assert safe_join("/", "") == "/"
    assert safe_join("/", ".") == "/"
    assert safe_join("/", "a/../b") == "/b"
    with pytest.raises(ValueError):
        safe_join("/", "/etc")
    with pytest.raises(ValueError):
        safe_join("/", "../etc")


def test_trailing_slash_base_normalized():
    assert safe_join("/srv/data/", "x") == "/srv/data/x"
    assert safe_join("/srv/data///", "x") == "/srv/data/x"
    assert safe_join("/srv/data/.", "x") == "/srv/data/x"


