def test_unicode_nfc_equivalent_sibling_is_outside():
    # composed e-acute vs decomposed e + combining acute are distinct lexically
    base = "/\u00e9"
    evil = "../\u0065\u0301"
    # reference: distinct strings -> outside -> ValueError
    with pytest.raises(ValueError):
        ref_safe_join(base, evil)
    with pytest.raises(ValueError):
        safe_join(base, evil)


def test_unicode_nfc_equivalent_sibling_reversed_is_outside():
    base = "/\u0065\u0301"
    evil = "../\u00e9"
    with pytest.raises(ValueError):
        ref_safe_join(base, evil)
    with pytest.raises(ValueError):
        safe_join(base, evil)


def test_unicode_nfc_nested_escape_is_outside():
    with pytest.raises(ValueError):
        safe_join("/\u00e9", "../\u0065\u0301/evil")
    with pytest.raises(ValueError):
        safe_join("/\u00e9", "../\u0065\u0301/a/b")
    with pytest.raises(ValueError):
        safe_join("/srv/caf\u00e9", "../caf\u0065\u0301/x")


def test_unicode_exact_match_stays_inside():
    assert safe_join("/\u00e9", ".") == "/\u00e9"
    assert safe_join("/\u00e9", "") == "/\u00e9"
    assert safe_join("/\u00e9", "sub") == "/\u00e9/sub"
    assert safe_join("/\u0065\u0301", "sub") == "/\u0065\u0301/sub"


# ---- property-based: equivalence to simple reference model ----

_ascii_path_chars = st.sampled_from(
    list("ab/._-") + ["..", ".", "x"]
)

def _path_piece():
    return st.text(alphabet=list("abAxZ09._-"), min_size=0, max_size=4)

def _rel_path():
    return st.lists(_path_piece(), min_size=0, max_size=4).map("/".join)

def _abs_base():
    return st.lists(_path_piece(), min_size=0, max_size=3).map(
        lambda parts: "/" + "/".join(parts)
    )


@given(base=_abs_base(), rel=_rel_path())
def test_property_equivalence_to_reference_model(base, rel):
    try:
        expected = ref_safe_join(base, rel)
    except (TypeError, ValueError):
        with pytest.raises(ValueError):
            safe_join(base, rel)
    else:
        assert safe_join(base, rel) == expected


_unicode_alphabet = list("a/b._-\u00e9\u0065\u0301\u00f1\u006e\u0303")

@given(
    base=st.text(alphabet=_unicode_alphabet, min_size=1, max_size=8).map(lambda s: "/" + s),
    tail=st.text(alphabet=_unicode_alphabet, min_size=1, max_size=8),
)
def test_property_unicode_equivalence_to_reference(base, tail):
    rel_variants = ["../" + tail, tail, tail + "/x"]
    for rel in rel_variants:
        try:
            expected = ref_safe_join(base, rel)
        except (TypeError, ValueError):
            with pytest.raises(ValueError):
                safe_join(base, rel)
        else:
            got = safe_join(base, rel)
            assert got == expected


@given(base=_abs_base(), rel=_rel_path())
def test_property_returned_result_is_normpath_join(base, rel):
    try:
        got = safe_join(base, rel)
    except ValueError:
        return
    root = posixpath.normpath(base)
    expected = posixpath.normpath(posixpath.join(root, rel))
    assert got == expected
    assert got == posixpath.normpath(got)


@given(base=_abs_base(), rel=_rel_path())
def test_property_inside_means_prefix_or_equal(base, rel):
    try:
        got = safe_join(base, rel)
    except ValueError:
        # escaping paths must truly be outside per lexical rule
        root = posixpath.normpath(base)
        result = posixpath.normpath(posixpath.join(root, rel))
        if root.endswith("/"):
            assert not result.startswith(root)
        else:
            assert result != root and not result.startswith(root + "/")
        return
    root = posixpath.normpath(base)
    if root.endswith("/"):
        assert got.startswith(root)
    else:
        assert got == root or got.startswith(root + "/")


@given(base=_abs_base())
def test_property_empty_and_dot_return_root(base):
    root = posixpath.normpath(base)
    assert safe_join(base, "") == root
    assert safe_join(base, ".") == root


@given(base=_abs_base(), rel=_rel_path(), suffix=_path_piece())
def test_property_appending_dotdot_stays_consistent(base, rel, suffix):
    # metamorphic: joining rel then suffix equals joining rel/suffix directly
    # whenever neither escapes
    try:
        mid = safe_join(base, rel)
    except ValueError:
        return
    try:
        a = safe_join(base, rel + "/" + suffix)
    except ValueError:
        # if extended escapes, direct join from mid with suffix may also escape or not;
        # just check reference agrees
        try:
            ref_safe_join(base, rel + "/" + suffix)
        except ValueError:
            pass
        else:
            raise AssertionError("reference says inside but impl raised")
        return
    b = None
    try:
        b = safe_join(mid, suffix)
    except ValueError:
        pass
    # mid is absolute so safe_join(mid, suffix) with relative suffix is defined;
    # both should equal normpath(join(root, rel/suffix))
    if b is not None:
        assert a == b
